export type LabCode = 'BE-201' | 'BE-202' | 'AL-301';

// Record over the union — the table must have an entry for every lab.
export type SeatMap = Record<LabCode, number>;

import type { SeatMap } from '../src/seats.ts';
const seats: SeatMap = { 'BE-201': 40, 'BE-202': 24, 'AL-301': 30 }; // all three
export { seats };

