export type Cache = Record<string, number>;

// Guard the lookup: a missing key falls back to 0, so the result is a number.
export function get(c: Cache, key: string): number {
  return c[key] ?? 0;
}

import { get } from '../src/cache.ts';
const hits: number = get({ a: 1 }, 'a');
export { hits };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { get } from '../src/cache.ts';
test('get', () => { assert.equal(get({ a: 1 }, 'a'), 1); assert.equal(get({ a: 1 }, 'z'), 0); });

